/* Медленно плывущий градиент фона. Пятна цвета — готовые радиальные градиенты,
   двигаются только transform: без перерисовки, без filter: blur, без background-position.
   Цвета — токены дизайн-системы (подставьте свои имена переменных). */
.gd-scene {
  --gd-c1: var(--primary, #4f46e5);
  --gd-c2: var(--accent, #0ea5e9);
  --gd-c3: var(--primary, #4f46e5);
  --gd-strength: 28%;                      /* насыщенность пятна в центре; выше 35% — перепроверьте контраст текста */
  --gd-ease: cubic-bezier(.37, 0, .63, 1); /* sine in-out: разворот без рывка */
  position: relative;
  isolation: isolate;                      /* фон с z-index:-1 остаётся внутри секции */
  overflow: hidden;
  overflow: clip;                          /* обрезает пятна по краю секции, горизонтальной прокрутки нет */
  background: var(--background, #ffffff);
  color: var(--text, #0f172a);
}
.gd-content { max-width: 760px; margin: 0 auto; padding: clamp(64px, 10vw, 128px) 16px; text-align: center; }
.gd-bg { position: absolute; inset: 0; z-index: -1; pointer-events: none; }
/* Низ секции растворяется в фоне страницы — нет резкого шва со следующим блоком.
   Если у следующей секции свой фон, уберите это правило. */
.gd-bg::after {
  content: "";
  position: absolute;
  inset: auto 0 0 0;
  height: 28%;
  background: linear-gradient(to bottom, transparent, var(--background, #ffffff));
}
.gd-blob { position: absolute; aspect-ratio: 1.35; }
.gd-blob::before {
  content: "";
  position: absolute;
  inset: 0;
  background: radial-gradient(closest-side, color-mix(in srgb, var(--gd-c) var(--gd-strength), transparent), transparent);
}
/* Размер — доля секции, но не меньше 520px: на телефоне пятно шире экрана и не выглядит точкой */
.gd-blob--a { --gd-c: var(--gd-c1); width: max(72%, 520px); top: -30%; left: -20%; }
.gd-blob--b { --gd-c: var(--gd-c2); width: max(64%, 480px); bottom: -34%; right: -18%; }
.gd-blob--c { --gd-c: var(--gd-c3); --gd-strength: 18%; width: max(46%, 360px); top: 18%; left: 34%; }

/* Сдвиг — в процентах от размера пятна (≈10% ширины секции), поворот ±12°, масштаб 0.94–1.08 */
@keyframes gd-drift-a { to { transform: translate3d(14%, 10%, 0); } }
@keyframes gd-drift-b { to { transform: translate3d(-12%, -9%, 0); } }
@keyframes gd-drift-c { to { transform: translate3d(-10%, 12%, 0); } }
@keyframes gd-morph {
  from { transform: rotate(-12deg) scale(.94); }
  to { transform: rotate(12deg) scale(1.08); }
}

/* Движение включаем только тем, кто не просил его уменьшить.
   Сдвиг (само пятно) и поворот (его ::before) идут с разными периодами — путь не повторяется.
   Последнее слово в animation — состояние из --gd-play: running или paused. */
@media (prefers-reduced-motion: no-preference) {
  .gd-blob, .gd-blob::before { will-change: transform; }
  .gd-blob--a { animation: gd-drift-a 12s var(--gd-ease) infinite alternate var(--gd-play, running); }
  .gd-blob--b { animation: gd-drift-b 16s var(--gd-ease) -5s infinite alternate var(--gd-play, running); }
  .gd-blob--c { animation: gd-drift-c 10s var(--gd-ease) -3s infinite alternate var(--gd-play, running); }
  .gd-blob--a::before { animation: gd-morph 18s var(--gd-ease) infinite alternate var(--gd-play, running); }
  .gd-blob--b::before { animation: gd-morph 20s var(--gd-ease) -8s infinite alternate var(--gd-play, running); }
  .gd-blob--c::before { animation: gd-morph 14s var(--gd-ease) -4s infinite alternate var(--gd-play, running); }
}

/* Пауза (animation-play-state: paused через переменную, пятна замирают на месте, без скачка):
   кнопка, секция вне экрана, фокус внутри содержимого, наведение на содержимое */
.gd-scene[data-gd-state="paused"],
.gd-scene.is-offscreen,
.gd-content:focus-within ~ .gd-bg { --gd-play: paused; }
@media (hover: hover) {
  .gd-content:hover ~ .gd-bg { --gd-play: paused; }
}

/* Кнопка паузы: 44px, в углу секции, контрастная иконка */
.gd-toggle {
  position: absolute;
  right: 16px;
  bottom: 16px;
  z-index: 1;
  display: inline-grid;
  place-items: center;
  width: 44px;
  height: 44px;
  padding: 0;
  border: 1px solid var(--border, #cbd5e1);
  border-radius: 999px;
  background: var(--surface, #ffffff);
  color: var(--text, #0f172a);
  cursor: pointer;
}
.gd-toggle[hidden] { display: none; }    /* без этой строки display:inline-grid перебивает hidden */
.gd-toggle:focus-visible { outline: 3px solid var(--text, #0f172a); outline-offset: 3px; }
.gd-ico { width: 18px; height: 18px; }
.gd-ico--play, .gd-scene[data-gd-state="paused"] .gd-ico--pause { display: none; }
.gd-scene[data-gd-state="paused"] .gd-ico--play { display: block; }

/* Уровень 1 по схеме iart: плывущий фон на всю секцию убираем целиком.
   Пятна стоят на своих местах — цвета и композиция те же, кнопку паузы прячет скрипт. */
@media (prefers-reduced-motion: reduce) {
  .gd-blob, .gd-blob::before { animation: none !important; transform: none !important; will-change: auto; }
}

