// Подключать в конце <body> или с defer. Кнопка паузы и остановка фона вне экрана.
(() => {
  const scenes = [...document.querySelectorAll('.gd-scene')];
  if (!scenes.length) return;
  const reduce = matchMedia('(prefers-reduced-motion: reduce)');
  const TEXT = { playing: 'Остановить движение фона', paused: 'Запустить движение фона' };
  const btnOf = scene => scene.querySelector('[data-gd-toggle]');
  const setState = (scene, state) => {
    scene.dataset.gdState = state;
    const btn = btnOf(scene);
    if (btn) { btn.setAttribute('aria-label', TEXT[state]); btn.title = TEXT[state]; }
  };
  scenes.forEach(scene => {
    setState(scene, scene.dataset.gdState === 'paused' ? 'paused' : 'playing');
    const btn = btnOf(scene);
    if (btn) btn.addEventListener('click', () =>
      setState(scene, scene.dataset.gdState === 'paused' ? 'playing' : 'paused'));
  });
  // Секция ушла с экрана — фон стоит и не тратит батарею. Проверка по прокрутке и смене размеров:
  // IntersectionObserver будил бы главный поток на каждом кадре идущей анимации.
  let raf = 0;
  const check = () => {
    raf = 0;
    const vh = innerHeight;
    scenes.forEach(s => { const r = s.getBoundingClientRect(); s.classList.toggle('is-offscreen', r.bottom <= 0 || r.top >= vh); });
  };
  const tick = () => { if (!raf) raf = requestAnimationFrame(check); };
  addEventListener('scroll', tick, { passive: true, capture: true }); // capture — и прокрутка внутри контейнера
  addEventListener('resize', tick);
  new ResizeObserver(tick).observe(document.body); // блок выше вырос или исчез — секция сдвинулась без прокрутки
  tick();
  // При «уменьшить движение» фон стоит (это делает CSS), кнопка паузы не нужна.
  // Настройку подхватываем без перезагрузки страницы.
  const sync = () => scenes.forEach(s => { const b = btnOf(s); if (b) b.hidden = reduce.matches; });
  reduce.addEventListener('change', sync);
  sync();
})();

gsap_alt:
Из npm, без CDN: npm i gsap. Когда брать: GSAP уже подключён на странице ради других эффектов. Сам по себе GSAP двигает пятна из главного потока (на каждом кадре скрипт пишет transform), а CSS-вариант целиком живёт в композиторе — для фона CSS дешевле. Разметку и CSS оставьте, но удалите блок @media (prefers-reduced-motion: no-preference) с animation (иначе CSS-анимация перебьёт transform, который пишет GSAP) и ванильный JS из поля js (иначе кнопка переключится дважды). Поворот ::before GSAP не достаёт: вложите в каждое пятно <span class="gd-shape"></span> и перенесите на него стили ::before. Код ниже — для одной секции; если их две, повторите тело mm.add для каждой. Затем:
import { gsap } from 'gsap';
import { ScrollTrigger } from 'gsap/ScrollTrigger';
gsap.registerPlugin(ScrollTrigger);
const mm = gsap.matchMedia();
mm.add('(prefers-reduced-motion: no-preference)', () => {
  const r = gsap.utils.random;
  const scene = document.querySelector('.gd-scene');
  const tweens = gsap.utils.toArray('.gd-blob', scene).flatMap(blob => [
    gsap.to(blob, { xPercent: r(-14, 14), yPercent: r(-12, 12), duration: r(10, 16), ease: 'sine.inOut', repeat: -1, yoyo: true }),
    gsap.fromTo(blob.querySelector('.gd-shape'), { rotation: -12, scale: 0.94 },
      { rotation: 12, scale: 1.08, duration: r(14, 20), ease: 'sine.inOut', repeat: -1, yoyo: true })
  ]);
  const btn = scene.querySelector('[data-gd-toggle]');
  const content = scene.querySelector('.gd-content');
  // user — пауза кнопкой, hold — наведение/фокус на содержимом, away — секция вне экрана
  let user = false, hold = 0, away = !ScrollTrigger.isInViewport(scene);
  const apply = () => tweens.forEach(t => t.paused(user || away || hold > 0));
  const onBtn = () => { user = !user; btn.setAttribute('aria-label', user ? 'Запустить движение фона' : 'Остановить движение фона'); scene.dataset.gdState = user ? 'paused' : 'playing'; apply(); };
  const on = () => { hold++; apply(); }, off = () => { hold = Math.max(0, hold - 1); apply(); };
  // Вне экрана фон стоит: ScrollTrigger, созданный внутри mm.add, matchMedia уберёт сам
  ScrollTrigger.create({ trigger: scene, start: 'top bottom', end: 'bottom top', onToggle: s => { away = !s.isActive; apply(); } });
  apply();
  btn.hidden = false; btn.addEventListener('click', onBtn);
  content.addEventListener('pointerenter', on); content.addEventListener('pointerleave', off);
  content.addEventListener('focusin', on); content.addEventListener('focusout', off);
  return () => { btn.hidden = true; scene.dataset.gdState = 'playing'; btn.setAttribute('aria-label', 'Остановить движение фона'); btn.removeEventListener('click', onBtn); content.removeEventListener('pointerenter', on); content.removeEventListener('pointerleave', off); content.removeEventListener('focusin', on); content.removeEventListener('focusout', off); };
});
// matchMedia сам откатывает твины и ScrollTrigger, когда человек включает «уменьшить движение»: пятна возвращаются на место, кнопка прячется.
// Проверено в Chromium с gsap 3.15 из npm: пауза кнопкой, наведением, фокусом и вне экрана, возобновление, откат при reduce.
